package xapi.jre.model;
import org.junit.Test;import static org.junit.Assert.*;import xapi.model.api.*;import xapi.model.content.*;import xapi.model.user.ModelUser;import xapi.source.lex.CharIterator;import xapi.util.api.*;import java.nio.file.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
/** Planner models and conditions originate from the same bytes, without IO during codec capture. */
public class ModelFileSnapshotTest {
 static class Service extends ModelServiceJre {Runnable next,onDecode;int writes,loads;@Override protected void dispatchFileOperation(Runnable r){next=r;}@Override protected <M extends Model>void doPersist(String type,M m,SuccessHandler<M> cb){writes++;super.doPersist(type,m,cb);}@Override public <M extends Model>void load(Class<M> c,ModelKey k,SuccessHandler<M> cb){loads++;throw new AssertionError("implicit hydration");}@Override protected <M extends Model>M deserialize(ModelManifest m,CharIterator chars,boolean direction,boolean hydrate){assertFalse(hydrate);if(onDecode!=null){Runnable r=onDecode;onDecode=null;r.run();}return super.deserialize(m,chars,direction,hydrate);}}
 static class Result<T> implements SuccessHandler<T>,ErrorHandler<Throwable>{T value;Throwable error;int count;public void onSuccess(T t){value=t;count++;}public void onError(Throwable t){error=t;count++;}T success(){assertEquals(1,count);if(error!=null)throw new AssertionError(error);return value;}}
 static ModelText text(Service s,String value){ModelText t=s.create(ModelText.class);t.setKey(s.newKey("child","day","1").getChild(t.getType(),"brush"));t.setText(value);return t;}
 static void raw(FileModelTransactionStore store,ModelStoreKey key,byte[] bytes)throws Exception{store.legacyWriteScope(key,()->{Path p=store.directory().resolve(key.relativePath());Files.createDirectories(p.getParent());Files.write(p,bytes);return null;});}
 @Test public void snapshotCapturesKeyAndDecodesExactlyReadBytesOutsideGate()throws Exception{Service s=new Service();try(FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("file-snapshot"))){s.attachTransactionStore(store);ModelText original=text(s,"OLD");ModelManifest manifest=s.findManifest(ModelText.class);byte[] old=s.encodeTransactionImage(manifest,original);ModelStoreKey key=s.transactionKey(original.getKey());raw(store,key,old);ModelText changed=text(s,"NEW");byte[] newer=s.encodeTransactionImage(manifest,changed);Result<ModelFileSnapshot<ModelText>> result=new Result<>();s.loadSnapshot(manifest,original.getKey(),result);original.getKey().setId("caller-mutated");s.onDecode=()->{AtomicReference<Throwable> failure=new AtomicReference<>();Thread t=new Thread(()->{try{raw(store,key,newer);}catch(Throwable e){failure.set(e);}});t.start();try{t.join(3000);}catch(InterruptedException e){throw new AssertionError(e);}assertFalse("decode must not hold gate",t.isAlive());assertNull(failure.get());};s.next.run();ModelFileSnapshot<ModelText> snapshot=result.success();assertEquals("OLD",snapshot.model().getText());assertArrayEquals(old,snapshot.record().value());assertArrayEquals(newer,store.read(key).value());assertEquals(key.canonicalKey(),snapshot.storeKey().canonicalKey());assertEquals("brush",snapshot.model().getKey().getId());}}
 @Test public void absenceRetainsConditionAndCallbacksRunOutsideGateOnce()throws Exception{Service s=new Service();try(FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("snapshot-absence"))){s.attachTransactionStore(store);ModelText t=text(s,"unused");Result<ModelFileSnapshot<ModelText>> result=new Result<>();s.loadSnapshot(s.findManifest(ModelText.class),t.getKey(),result);s.next.run();assertNull(result.success().model());assertFalse(result.value.record().exists());Result<ModelFileSnapshot<ModelText>> throwing=new Result<ModelFileSnapshot<ModelText>>(){@Override public void onSuccess(ModelFileSnapshot<ModelText> value){super.onSuccess(value);Thread worker=new Thread(()->{try{store.read(s.transactionKey(t.getKey()));}catch(Exception e){throw new AssertionError(e);}});worker.start();try{worker.join(3000);}catch(InterruptedException e){throw new AssertionError(e);}assertFalse(worker.isAlive());throw new IllegalStateException("observer");}};s.loadSnapshot(s.findManifest(ModelText.class),t.getKey(),throwing);try{s.next.run();fail();}catch(IllegalStateException expected){}assertEquals(1,throwing.count);assertNull(throwing.error);}}
 @Test public void codecDoesNotAutosaveOrHydrateAndRejectsCorruptIdentity()throws Exception{Service s=new Service();try(FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("snapshot-codec"))){s.attachTransactionStore(store);ModelContent root=s.create(ModelContent.class);root.setKey(s.newKey("child",root.getType(),"root"));ModelUser author=s.create(ModelUser.class);author.setKey(s.newKey("child",author.getType(),"author"));root.setAuthor(author);ModelContent reference=s.create(ModelContent.class);reference.setKey(s.newKey("child",reference.getType(),"ref"));root.related().add(reference);byte[] image=s.encodeTransactionImage(s.findManifest(ModelContent.class),root);ModelContent decoded=s.decodeSnapshotImage(s.findManifest(ModelContent.class),root.getKey(),image);assertEquals("author",decoded.getAuthor().getKey().getId());assertEquals(0,s.loads);assertEquals(0,s.writes);assertFalse(Files.exists(store.directory().resolve("child/content/ref")));try{s.decodeSnapshotImage(s.findManifest(ModelContent.class),s.newKey("child",root.getType(),"other"),image);fail();}catch(IOException expected){}try{s.decodeSnapshotImage(s.findManifest(ModelContent.class),root.getKey(),new byte[]{(byte)0xff});fail();}catch(IOException expected){}}}
 @Test public void attachedClosedStoreHasTypedUnavailableWithoutChangingBorrowIdentity()throws Exception{Service s=new Service();FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("snapshot-closed"));s.attachTransactionStore(store);ModelText t=text(s,"x");store.close();assertSame(store,s.transactionStore());Result<ModelFileSnapshot<ModelText>> result=new Result<>();s.loadSnapshot(s.findManifest(ModelText.class),t.getKey(),result);s.next.run();assertTrue(result.error instanceof FileModelTransactionStore.Unavailable);assertEquals(1,result.count);}
}
